<script setup lang="ts">
import {computed,ref} from 'vue';
const props=defineProps<{players:{name:string;cards:number[]}[];cardNames:Map<number,{name:string}>;activeTab?:string}>();
const emit=defineEmits<{tab:[name:string];apply:[side:number,cards:number[]]}>();
type Saved={name:string;cards:number[]};
const records=ref<Saved[]>([]),localTab=ref('首页'),name=ref(''),side=ref(0),choice=ref(''),message=ref('');
const tab=computed(()=>props.activeTab??localTab.value);
const key='yxp.favorite-decks.v1';
function normalized(s:string){return s.normalize('NFKC').trim().toLocaleLowerCase()}
try{const saved=JSON.parse(localStorage.getItem(key)??'[]');if(Array.isArray(saved)){const seen=new Set<string>();records.value=saved.filter(r=>{if(!r||typeof r.name!=='string'||!normalized(r.name)||r.name.length>40||!Array.isArray(r.cards)||r.cards.length<3||r.cards.length>8||!r.cards.every(Number.isInteger)||seen.has(normalized(r.name)))return false;seen.add(normalized(r.name));return true}).slice(0,10);}}catch{message.value='无法读取本地收藏，请检查浏览器存储设置。'}
function persist(next:Saved[]){try{localStorage.setItem(key,JSON.stringify(next));records.value=next;return true}catch{message.value='保存失败：浏览器本地存储不可用或空间不足。';return false}}
function save(){message.value='';const n=name.value.trim();if(!n||n.length>40){message.value='请填写1–40字的卡组名称。';return}if(records.value.some(r=>normalized(r.name)===normalized(n))){message.value='卡组名称已存在，请使用其他名称。';return}if(records.value.length>=10){message.value='最多收藏10条，请先删除一条。';return}const cards=props.players[side.value]?.cards;if(!cards||cards.length<3||cards.length>8){message.value='请等待卡组加载。';return}if(persist([...records.value,{name:n,cards:[...cards]}])){message.value=`已收藏“${n}”`;name.value='';}}
function apply(r:Saved,target:number){if(r.cards.some(id=>!props.cardNames.has(id))){message.value='卡组包含当前版本未知卡牌，无法导入。';return}emit('apply',target,[...r.cards]);message.value=`已将“${r.name}”导入${target===0?'甲方':'乙方'}`}
function change(t:string){localTab.value=t;message.value='';emit('tab',t)}
function remove(r:Saved){if(persist(records.value.filter(v=>v!==r))){if(choice.value===r.name)choice.value='';message.value=`已删除“${r.name}”`;}}
</script>
<template><section class="favorites"><nav aria-label="页面标签"><button v-for="t in ['首页','收藏夹','对局追踪','战绩码']" :key="t" type="button" :aria-pressed="tab===t" @click="change(t)">{{t}}{{t==='收藏夹'?` (${records.length}/10)`:''}}</button></nav><p v-if="message" role="status">{{message}}</p>
<div v-if="tab==='首页'&&records.length" class="favorite-quick"><label>收藏卡组<select v-model="choice"><option value="">按名称选择</option><option v-for="r in records" :key="r.name" :value="r.name">{{r.name}}</option></select></label><button type="button" :disabled="!choice" @click="apply(records.find(r=>r.name===choice)!,0)">导入甲方</button><button type="button" :disabled="!choice" @click="apply(records.find(r=>r.name===choice)!,1)">导入乙方</button></div>
<div v-if="tab==='收藏夹'"><h2>卡组收藏夹</h2><p>保存3–8张卡牌及等级，按当前顺序导入；角色、仙命、属性和手牌保持原值。收藏保存在当前浏览器，最多10条。</p><form @submit.prevent="save"><label>保存来源<select v-model.number="side"><option :value="0">甲方 · {{players[0]?.name}}</option><option :value="1">乙方 · {{players[1]?.name}}</option></select></label><label>卡组名称<input v-model="name" maxlength="40" placeholder="输入不重复的名称" required></label><button type="submit">保存当前卡组</button></form><p v-if="!records.length">还没有收藏。先在首页排好卡，再到这里保存。</p><article v-for="r in records" :key="r.name"><h3>{{r.name}} <small>{{r.cards.length}}张</small></h3><ol><li v-for="(id,i) in r.cards" :key="i">{{cardNames.get(id)?.name??`未知卡牌 #${id}`}} · {{Math.floor(id/10000)%100+1}}级</li></ol><button type="button" @click="apply(r,0)">导入甲方</button><button type="button" @click="apply(r,1)">导入乙方</button><button type="button" @click="remove(r)">删除收藏</button></article></div></section></template>
<style scoped>.favorites{margin:12px 0 20px}.favorites nav,.favorite-quick,.favorites form{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.favorites nav button[aria-pressed=true]{background:#365c50;color:#fff}.favorites button,.favorites input,.favorites select{padding:9px 14px;border:1px solid #b7ad97;border-radius:6px}.favorites button{cursor:pointer}.favorites button:disabled{opacity:.5;cursor:default}.favorite-quick{margin-top:15px}.favorites article{padding:18px;margin:16px 0;border:1px solid #b7ad97;border-radius:8px;background:#faf7ee}.favorites article button{margin-right:10px}.favorites ol{display:flex;flex-wrap:wrap;gap:12px 28px;padding-left:24px}.favorites small{font-weight:normal;color:#777}.favorites label{display:flex;gap:8px;align-items:center}</style>
